# Generated by release/homebrew/formula.sh of the wolfpack repository for each release.
class Wolfpack < Formula
  desc "Statically typed language that compiles to readable TypeScript, Go and Rust"
  homepage "https://github.com/realfamousbae/wolfpack"
  license any_of: ["MIT", "Apache-2.0"]

  # The macOS archive is universal: the same file for both processors.
  on_macos do
    on_arm do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.5.1/wolfpack-macos-universal.tar.gz"
      sha256 "6de7b1657a5f892a872ece472bc6809eb85eadac773f5fe09196fe237db9df2b"
    end
    on_intel do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.5.1/wolfpack-macos-universal.tar.gz"
      sha256 "6de7b1657a5f892a872ece472bc6809eb85eadac773f5fe09196fe237db9df2b"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.5.1/wolfpack-linux-x64.tar.gz"
      sha256 "8bc873f4561ff278ace9e9f5d503be93549c3e61b3b9e1ed0d911fb64498376e"
    end
    on_arm do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.5.1/wolfpack-linux-arm64.tar.gz"
      sha256 "4f4db6f7ae6ead16621a48aad56fcba0054e317b3deffccee11801f30f7b82ff"
    end
  end

  def install
    bin.install "wolf"
  end

  def caveats
    <<~EOS
      wolf runs programs in its own VM without other tools (wolf run --vm).
      To build and run them as TypeScript, Go or Rust, install those tools with:
        wolf setup
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/wolf --version")
    system bin/"wolf", "new", "hello"
    assert_equal "Hello, wolfpack!\n", shell_output("cd hello && #{bin}/wolf run --vm")
  end
end
